    /// A worker reports a result with the token it holds.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
    pub struct WorkReportedPayload {
        /// Field `token`.
        pub token: u64,
    }

    /// The payload of event `lease-granted`: Lease granted.
    ///
    /// A worker is given the job under a new token.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
    pub struct LeaseGrantedPayload {}

    /// The payload of event `job-completed`: Job completed.
